[Form]
public class NDXCentralWarehouseSalesDistribution extends FormRun
{
    QueryBuildRange         qbRangeTable;
    QueryBuildRange         qbRangeLine, qbRangeLineSum, qbRangeLineCustSum;
    QueryBuildRange         qbRangeDistrictGroup;
    QueryBuildRange         qbRangeSalesDistrict;
    QueryBuildRange         qbRangeCentralStore;

    int                     backColorMarked;
    int                     textColorMarked;
    int                     backColorUnMarked;
    int                     textColorUnMarked;

    CustAccount             FilterCentralStoreId;

}

public void init()
{
    CustTable           custTable;
    super();

    backColorMarked         = WinAPI::rgb2int(255,244,48);
    textColorMarked         = WinAPI::rgb2int(20,12,255);
    backColorUnMarked       = WinAPI::rgb2int(255,255,255);
    textColorUnMarked       = WinAPI::rgb2int(0,0,0);

    if (element.args() && element.args().dataset() && element.args().dataset() == tablenum(CustTable))
    {
        custTable = element.args().record();
        FilterCentralStoreId = custTable.AccountNum;
        qbRangeCentralStore.value(FilterCentralStoreId);
        NDX_CentralStore_DS.executeQuery();
    }
}

void setRangeTable()
{
    if (NDX_CentralStore)
    {
        qbRangeTable.value(NDX_CentralStore.CentralStoreId);
    }
    else
    {
        qbRangeTable.value('-1');
    }

    NDX_CentralStoreDistributionTable_DS.executeQuery();
    if (!NDX_CentralStoreDistributionTable)
    {
        element.setRangeLine();
        element.setRangeLineSum();
        element.setRangeLineCustSum();
    }
}

void setRangeLine()
{
    if (NDX_CentralStoreDistributionTable.CentralStoreId == NDX_CentralStore.CentralStoreId)
    {
        qbRangeLine.value(NDX_CentralStoreDistributionTable.CSDId);
    }
    else
    {
        qbRangeLine.value('-1');
    }
    NDX_CentralStoreDistributionLine_DS.executeQuery();

}

void setRangeLineSum()
{
    if (NDX_CentralStoreDistributionTable.CentralStoreId == NDX_CentralStore.CentralStoreId)
    {
        qbRangeLineSum.value(NDX_CentralStoreDistributionTable.CSDId);
    }
    else
    {
        qbRangeLineSum.value('-1');
    }
    NDX_CentralStoreDistributionLineSum_DS.executeQuery();

}

void setRangeLineCustSum()
{
    if (NDX_CentralStoreDistributionTable.CentralStoreId == NDX_CentralStore.CentralStoreId)
    {
        qbRangeLineCustSum.value(NDX_CentralStoreDistributionTable.CSDId);
    }
    else
    {
        qbRangeLineCustSum.value('-1');
    }

    NDX_CentralStoreDistributionLineCustSum_DS.executeQuery();

}

void setRangeLineGroupSalesDistrict()
{
    if (NDX_CentralStoreDistributionTable.CentralStoreId == NDX_CentralStore.CentralStoreId)
    {
        qbRangeSalesDistrict.value(NDX_CentralStoreDistributionTable.CSDId);
    }
    else
    {
        qbRangeSalesDistrict.value('-1');
    }

    NDX_CentralStoreDistributionLineGroupSalesDistrict_DS.executeQuery();

}

private void executeSetAction(str _menuItemName)
{
    Args args = new Args();
    args.record(NDX_CentralStoreDistributionTable);
    args.parm(NDX_CentralStore.CentralStoreId);

    args.caller(this);

    new MenuFunction(_menuItemName, MenuItemType::Action).run(args);
}

private void activateButtons(boolean _activate)
{
    NDXCheckAlliance.enabled(_activate);
    NDXCSDCreateSet.enabled(_activate);
    NDXCSDCopySet.enabled(_activate);
}

public int task(int _p1)
{
    int ret;

    #Task

    if(_p1 == #taskSwitchToDetailsView)
    {
        this.activateButtons(true);
    }
    else if(_p1 == #taskSwitchToGridView)
    {
        this.activateButtons(false);
    }

    ret = super(_p1);

    return ret;
}

public void init()
{
    QueryBuildDataSource        qbDataSource;
    super();

    qbDataSource = this.query().dataSourceTable(tablenum(NDX_CentralStore));
    qbDataSource.clearDynalinks();
    qbDataSource.clearRanges();

    qbDataSource.addSortField(fieldnum(NDX_CentralStore, CentralStoreId), SortOrder::Descending);

    qbRangeCentralStore = qbDataSource.addRange(fieldnum(NDX_CentralStore,  CentralStoreId));

}

public void linkActive()
{
    NDX_CentralStore    dynaLinkTableMain;

    if (element.args() && element.args().record() && element.args().record().TableId == tableNum(NDX_CentralStore))
    {
        dynaLinkTableMain = element.args().record();
        NDX_CentralStore_Q.allowCrossCompany(true);
        NDX_CentralStore_Q.clearCompanyRange();
        NDX_CentralStore_Q.addCompanyRange(dynaLinkTableMain.dataAreaId);
        qbRangeCentralStore.value(dynaLinkTableMain.CentralStoreId);
    }
    super();
}

public int active()
{
    int ret;

    ret = super();

    element.setRangeTable();

    return ret;
}

