public boolean validateDelete()
{
    boolean ret;
    NDX_CentralStoreDistributionLine_DS.research();
    if(NDX_CentralStoreDistributionLine)
    {
        Warning(strFmt("@NDXBase:NDXWarningRecordsStillExist", "@NDX:NDXCentralStoreDistributionLine"));
        ret = false;
    }
    else
    {
        ret = super();
    }
    return ret;
}

