}

public void init()
{
    QueryBuildDataSource        qbDataSource;
    super();
    qbDataSource = this.query().dataSourceTable(tablenum(NDX_CentralStoreDistributionLine));
    qbDataSource.clearDynalinks();
    qbDataSource.clearRanges();

    qbDataSource.addSortField(fieldnum(NDX_CentralStoreDistributionLine, smmSalesDistrictId), SortOrder::Ascending);
    qbDataSource.addSortField(fieldnum(NDX_CentralStoreDistributionLine, CustAccount), SortOrder::Descending);

    qbRangeLine = qbDataSource.addRange(fieldnum(NDX_CentralStoreDistributionLine,  CSDId));

