public void write()
{
    super();

    NDX_CentralStoreDistributionTable.setCSDPct();
    NDX_CentralStoreDistributionLine_DS.research(true);
    NDX_CentralStoreDistributionLineGroupSalesDistrict_DS.executeQuery();
}

public boolean leaveRecord(boolean _forceUpdate = false)
{
    boolean ret;

    ret = super(_forceUpdate);

    NDX_CentralStoreDistributionLineSum_DS.executeQuery();
    NDX_CentralStoreDistributionLineCustSum_DS.executeQuery();

    return ret;
}

public void displayOption(Common _record, FormRowDisplayOption _options)
{
    NDX_CentralStoreDistributionLine    lNDX_CentralStoreDistributionLine;

    lNDX_CentralStoreDistributionLine = _record;
    super(_record, _options);

    if (lNDX_CentralStoreDistributionLine.smmSalesDistrictId == NDX_CentralStoreDistributionLineGroupSalesDistrict.smmSalesDistrictId)
    {
        _options.backColor(backColorMarked);
        _options.textColor(textColorMarked);
    }
    else
    {
        _options.backColor(backColorUnMarked);
        _options.textColor(textColorUnMarked);
    }
}

public void init()
{
    QueryBuildDataSource        qbDataSource;
    QueryBuildFieldList         fieldList;

    super();
    qbDataSource = this.query().dataSourceTable(tablenum(NDX_CentralStoreDistributionLine));
    qbDataSource.clearDynalinks();
    qbDataSource.clearRanges();

    qbDataSource.addGroupByField(fieldnum(NDX_CentralStoreDistributionLine, CSDId));

    qbDataSource.orderMode(OrderMode::GroupBy);
    fieldList           = qbDataSource.fields();

    fieldList.addField(fieldnum(NDX_CentralStoreDistributionLine, CSDPct), SelectionField::Sum);
    fieldList.addField(fieldnum(NDX_CentralStoreDistributionLine, CSDPrice), SelectionField::Sum);

    qbRangeLineSum = qbDataSource.addRange(fieldnum(NDX_CentralStoreDistributionLine,  CSDId));

}

public void displayOption(Common _record, FormRowDisplayOption _options)
{
    NDX_CentralStoreDistributionLine    lNDX_CentralStoreDistributionLine;
    ;
    lNDX_CentralStoreDistributionLine = _record;
    super(_record, _options);

    if (lNDX_CentralStoreDistributionLine.CSDPct < 99.5)
    {
        _options.backColor(WinAPI::rgb2int(231,255,20));
        _options.textColor(WinAPI::rgb2int(255,15 ,63));
    }
    else
    {
        _options.backColor(backColorUnMarked);
        _options.textColor(textColorUnMarked);
    }
}

public int active()
{
    int ret;

    ret = super();

    NDX_CentralStoreDistributionLine_DS.research(true);

    return ret;
}

public void init()
{
    Query                   q = new Query();
    QueryBuildDataSource    qbds;
    QueryBuildFieldList     qbfl;

    super();

    qbds    = q.addDataSource(tablenum(NDX_CentralStoreDistributionLine));

    qbRangeSalesDistrict = qbds.addRange(fieldnum(NDX_CentralStoreDistributionLine,  CSDId));

    qbds.orderMode(OrderMode::GroupBy);
    qbds.addGroupByField(fieldnum(NDX_CentralStoreDistributionLine, smmSalesDistrictId));

    qbfl = qbds.fields();
    qbfl.addField(fieldnum(NDX_CentralStoreDistributionLine, CSDPct), SelectionField::Sum);
    qbfl.addField(fieldnum(NDX_CentralStoreDistributionLine, CSDPrice), SelectionField::Sum);

    this.query(q);
}

public void init()
{
    QueryBuildDataSource        qbDataSource, qbds2;
    QueryBuildFieldList         fieldList;

    super();
    qbDataSource = this.query().dataSourceTable(tablenum(NDX_CentralStoreDistributionLine));
    qbDataSource.clearDynalinks();
    qbDataSource.clearRanges();

    qbDataSource.addGroupByField(fieldnum(NDX_CentralStoreDistributionLine, CSDId));

    qbDataSource.orderMode(OrderMode::GroupBy);
    fieldList           = qbDataSource.fields();

    fieldList.addField(fieldnum(NDX_CentralStoreDistributionLine, CSDPct), SelectionField::Sum);
    fieldList.addField(fieldnum(NDX_CentralStoreDistributionLine, CSDPrice), SelectionField::Sum);

    qbds2 = qbDataSource.addDataSource(tablenum(CustTable));
    qbds2.addlink(fieldnum(NDX_CentralStoreDistributionLine, CustAccount), fieldnum(CustTable, AccountNum));
    qbds2.relations(true);
    qbds2.joinMode(JoinMode::NoExistsJoin);

    qbRangeLineCustSum = qbDataSource.addRange(fieldnum(NDX_CentralStoreDistributionLine,  CSDId));

}

